function validate([date]) {
  if (typeof date !== 'string' || date.length !== 10) return 'date has exactly 10 characters.';
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return 'date looks like yyyy-mm-dd: digits, with hyphens at positions 4 and 7.';
  const year = Number(date.slice(0, 4));
  const month = Number(date.slice(5, 7));
  const day = Number(date.slice(8));
  if (year < 1900 || year > 2100) return 'The year is between 1900 and 2100.';
  if (month < 1 || month > 12) return 'The month is between 01 and 12.';
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1];
  if (day < 1 || day > days) return 'The day must exist in that month (mind leap years).';
  return null;
}

