function convertDateToBinary(date) {
  const parts = date.split('-');
  const converted = [];
  for (const part of parts) {
    let value = Number(part);
    let bits = '';
    while (value > 0) {
      bits = (value % 2) + bits;
      value = Math.floor(value / 2);
    }
    converted.push(bits);
  }
  return converted.join('-');
}

