function generate(rand, size) {
  // The input always has 10 characters, so both sizes draw any real date in the allowed range.
  const year = rand() < 0.2 ? [1900, 2000, 2047, 2048, 2100][Math.floor(rand() * 5)] : 1900 + Math.floor(rand() * 201);
  const month = 1 + Math.floor(rand() * 12);
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1];
  // Month ends and firsts are favoured a little, since they have the most and the fewest bits.
  const day = rand() < 0.3 ? (rand() < 0.5 ? 1 : days) : 1 + Math.floor(rand() * days);
  const pad = v => String(v).padStart(2, '0');
  return [year + '-' + pad(month) + '-' + pad(day)];
}
